 * @hidden N
*/
scwin.setCorpInfo = async function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    const returnKey = "" + dma_pageContext.get("returnKey") + "";
    try {
        scwin.frame.setCorpInfo(isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, fssUnqNo);
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00171' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
    /* sdd-asis-lifecycle:end */
};
